(function(E){ const x = E["mkt-m1"] = E["mkt-m1"] || {units:{}}; x.units["mkt-1"] = {"grammar":{"id":"c-mkt-1-g","level":"B1","course":"marketing","unit":"mkt-1","title":"Then and now: used to, and now + present simple","titleTr":"Önce ve şimdi: used to ve now + geniş zaman","titleFa":"قبلاً و حالا: used to و now + حال ساده","formsTable":{"headers":{"en":["Then (not true now)","Now"],"tr":["Önce (artık doğru değil)","Şimdi"],"fa":["قبلاً (حالا دیگر نه)","حالا"]},"rows":[["We used to make towels only for other brands.","Now we also sell our own brand."],["We didn't use to have a web shop.","Now we sell online every day."],["Did you use to sell in Germany?","Do you sell in Germany now?"]]},"wrong":"We use to make towels only for other brands.","right":"We used to make towels only for other brands.","blank":{"sentence":"She ___ design labels for other companies.","word":"used to","distractors":["use to","is used to"]},"wrong2":"We are used to sell only in Turkey.","right2":"We used to sell only in Turkey.","blank2":{"sentence":"Did the company ___ sell anything under its own name?","word":"use to","distractors":["used to","using to"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Past habit, not true now: used to + base verb.","tr":"Artık doğru olmayan geçmiş alışkanlık: used to + yalın fiil.","fa":"عادت گذشته که حالا دیگر نیست: used to + فعل ساده.","ex":"We used to make towels only for other brands."},{"en":"Today's fact: present simple, often with now.","tr":"Bugünkü durum: geniş zaman, çoğu zaman now ile.","fa":"واقعیت امروز: حال ساده، اغلب با now.","ex":"Now we also sell our own brand."},{"en":"Questions and negatives: did or didn't + use to.","tr":"Soru ve olumsuz: did ya da didn't + use to.","fa":"سؤال و منفی: did یا didn't + use to.","ex":"Did you use to export? We didn't use to."},{"en":"be used to + -ing is different: \"be familiar with\".","tr":"be used to + -ing farklıdır: \"alışkın olmak\".","fa":"be used to + ‎-ing فرق دارد: «عادت داشتن به».","ex":"Our sales team is used to selling on price."}],"test":{"en":"Can you add \"but not any more\"? Then use used to.","tr":"Sonuna \"ama artık değil\" ekleyebiliyor musun? O zaman used to kullan.","fa":"می‌توانی آخرش «ولی دیگر نه» اضافه کنی؟ پس used to بیاور."},"contrast":{"en":"Turkish says a past habit with the -ar/-ır + -dı ending (yapardık) and Persian with the past continuous (می‌ساختیم). English needs used to, and learners often drop the -d or add be.","tr":"Türkçede geçmişteki alışkanlık geniş zamanın hikâyesiyle anlatılır: \"yapardık\". İngilizcede bunun için used to gerekir; en sık hatalar -d'yi düşürmek (use to) ya da başına be eklemektir (are used to).","fa":"در فارسی عادت گذشته را با ماضی استمراری می‌گوییم («می‌ساختیم»). انگلیسی برای همین معنا used to دارد؛ اشتباه رایج این است که ‎-d حذف شود (use to) یا be اضافه شود (are used to)."}},"errorWatch":[{"find":["we use to make","we use to sell","we use to export","we are used to make","we are used to sell","we are used to export","did you used to","did mavera used to"],"fix":{"en":"For a past habit that is not true now: used to + verb (\"We used to make...\"). In questions: did + use to.","tr":"Artık doğru olmayan geçmiş alışkanlık için: used to + fiil (\"We used to make...\"). Soruda: did + use to.","fa":"برای عادت گذشته که حالا دیگر نیست: used to + فعل («We used to make...»). در سؤال: did + use to."}}]},"b2":{"id":"c-mkt-1-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-1","title":"News about the future: be set to, be due to, be about to","titleTr":"Gelecekle ilgili haberler: be set to, be due to, be about to","titleFa":"خبر درباره‌ی آینده: be set to، be due to، be about to","formsTable":{"headers":{"en":["Form","Meaning","Example"],"tr":["Yapı","Anlam","Örnek"],"fa":["ساختار","معنی","مثال"]},"rows":[["be set to","planned and expected","The brand is set to launch in December."],["be due to","on a schedule, often with a date","The samples are due to arrive on Friday."],["be about to","very soon","We are about to open the web shop."]]},"wrong":"The new range is set to launching in December.","right":"The new range is set to launch in December.","blank":{"sentence":"The first stock is due ___ in our UK warehouse on 4 November.","word":"to arrive","distractors":["arriving","to arriving"]},"wrong2":"We are about opening our UK web shop.","right2":"We are about to open our UK web shop.","blank2":{"sentence":"Our web shop is about ___ its doors to UK customers.","word":"to open","distractors":["opening","open"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Planned and expected: be set to + verb.","tr":"Planlanmış ve beklenen: be set to + fiil.","fa":"برنامه‌ریزی‌شده و مورد انتظار: be set to + فعل.","ex":"The brand is set to launch in December."},{"en":"On a schedule, often with a date: be due to + verb.","tr":"Takvime bağlı, çoğu zaman tarihli: be due to + fiil.","fa":"طبق برنامه، اغلب با تاریخ: be due to + فعل.","ex":"The samples are due to arrive on Friday."},{"en":"Very soon: be about to + verb.","tr":"Çok yakında: be about to + fiil.","fa":"خیلی زود: be about to + فعل.","ex":"We are about to open the web shop."}],"test":{"en":"Is there a plan or a date? Use be set to or be due to. Is it minutes or days away? Use be about to.","tr":"Bir plan ya da tarih var mı? be set to ya da be due to kullan. Dakikalar ya da günler mi kaldı? be about to kullan.","fa":"برنامه یا تاریخی هست؟ be set to یا be due to بیاور. چند دقیقه یا چند روز بیشتر نمانده؟ be about to بیاور."},"contrast":{"en":"Turkish says \"açılmak üzere\" and \"aralık ayında piyasaya çıkacak\"; Persian says «قرار است» and «در آستانه‌ی». English builds all three with be + set/due/about + to + base verb.","tr":"Türkçede \"açılmak üzere\" (be about to) ve \"aralık ayında piyasaya çıkması planlanıyor\" (be set to) gibi kalıplar var. İngilizce üçünü de be + set/due/about + to + yalın fiil ile kurar.","fa":"در فارسی «قرار است در ماه دسامبر عرضه شود» (be set to یا be due to) و «در آستانه‌ی افتتاح است» (be about to) را داریم. انگلیسی هر سه را با be + set/due/about + to + فعل ساده می‌سازد."}},"errorWatch":[{"find":["set to launching","set to opening","due to arriving","we are about opening","we are about launching","is about to opening"],"fix":{"en":"After be set to, be due to and be about to, use the base verb: \"is set to launch\", \"is about to open\".","tr":"be set to, be due to ve be about to'dan sonra yalın fiil kullan: \"is set to launch\", \"is about to open\".","fa":"بعد از be set to و be due to و be about to فعل ساده بیاور: «is set to launch» و «is about to open»."}}],"useIn":{"en":"B2: in your \"About us\" text, announce one future event with be set to, be due to or be about to.","tr":"B2: \"Hakkımızda\" metninde gelecekteki bir olayı be set to, be due to ya da be about to ile duyur.","fa":"B2: در متن «درباره‌ی ما»، یک رویداد آینده را با be set to یا be due to یا be about to اعلام کن."},"exitItem":{"from":"mkt-1","kind":"blank","prompt":"Our new website is set ___ next month.","options":["going live","to go live","go live"],"correct":1}},"vocab":{"id":"c-mkt-1-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-1","goals":["career"],"title":{"en":"Brand Basics","tr":"Markanın Temelleri","fa":"مبانی برند"},"cards":[{"word":"own brand","sentence":"The company now sells towels under its own brand.","meaning":{"en":"Products sold with your company's name on them, not another company's.","tr":"kendi markası","fa":"برند خود شرکت"}},{"word":"private label","sentence":"For years we made private-label towels for a German retailer.","gap":"private-label","accept":["private-label","private label"],"meaning":{"en":"Products made by one company and sold under another company's name.","tr":"özel marka üretimi (private label)","fa":"تولید با برند مشتری (پرایوت لیبل)"}},{"word":"launch","sentence":"We launch the new range in December.","meaning":{"en":"To start selling a new product.","tr":"piyasaya sürmek, lansman yapmak","fa":"عرضه کردن؛ لانچ کردن"}},{"word":"brand voice","sentence":"Our brand voice is warm and plain in every post.","meaning":{"en":"The way a brand always sounds, in every text.","tr":"marka sesi","fa":"صدای برند"}},{"word":"product range","sentence":"Our product range includes towels, bathrobes and hand towels.","meaning":{"en":"All the products of one kind that a company sells.","tr":"ürün yelpazesi","fa":"سبد محصولات"}},{"word":"tone","sentence":"The tone of a complaint reply is more serious.","meaning":{"en":"How a text sounds in one moment.","tr":"ton","fa":"لحن"}},{"word":"brand awareness","sentence":"Nobody in the UK knows us yet, so our brand awareness is close to zero.","meaning":{"en":"How well people know and recognise a brand.","tr":"marka bilinirliği","fa":"آگاهی از برند"}},{"word":"target market","sentence":"Germany is our first target market.","meaning":{"en":"A country or group of customers a company wants to sell to.","tr":"hedef pazar","fa":"بازار هدف"}},{"word":"competitor","sentence":"Our main competitor in Germany sells cheaper towels.","meaning":{"en":"A company that sells similar products.","tr":"rakip","fa":"رقیب"}},{"word":"heritage","sentence":"Our heritage is real: almost thirty years of weaving in the same town.","meaning":{"en":"The history and traditions that a company or a place has.","tr":"köklü geçmiş, miras","fa":"پیشینه؛ میراث"}}]},"judge":{"id":"c-mkt-1-j","course":"marketing","unit":"mkt-1","type":"judge","title":{"en":"Is this in the voice?","tr":"Bu marka sesine uyuyor mu?","fa":"این با صدای برند هماهنگ است؟"},"prompt":"A coffee roaster in Izmir, open since 2011. Its voice sheet says: warm, plain, exact. Four lines for its website.","parts":["True","Specific","In the voice"],"instruction":{"en":"Tap what each line does well. A line for the website needs all three.","tr":"Her satırın iyi yaptığı şeylere dokun. Web sitesine girecek satırda üçü de olmalı.","fa":"روی کارهایی که هر خط درست انجام داده بزن. خطی که روی سایت می‌رود باید هر سه را داشته باشد."},"items":[{"by":"AI tool","answer":"We are a world-leading luxury coffee house with centuries of tradition.","present":[],"fix":{"en":"Not true and not specific: the company opened in 2011. Start from a fact: \"We have roasted coffee in Izmir since 2011.\"","tr":"Doğru değil, net de değil: şirket 2011'de açıldı. Bir gerçekle başla: \"We have roasted coffee in Izmir since 2011.\"","fa":"نه درست است نه دقیق: شرکت در سال ۲۰۱۱ تأسیس شده. از یک واقعیت شروع کن: «We have roasted coffee in Izmir since 2011.»"}},{"by":"AI tool","answer":"We offer high-quality products for all your needs.","present":["True"],"fix":{"en":"Maybe true, but any brand could say it. Name the product and one fact.","tr":"Doğru olabilir, ama bunu her marka söyleyebilir. Ürünü ve bir gerçeği söyle.","fa":"شاید درست باشد، ولی هر برندی می‌تواند این را بگوید. اسم محصول و یک واقعیت را بگو."}},{"by":"Good model","answer":"We roast your order on Tuesday and post it on Wednesday, so it reaches you fresh.","present":["True","Specific","In the voice"],"fix":null},{"by":"Junior writer","answer":"Our beans are processed in compliance with applicable roasting specifications.","present":["True","Specific"],"fix":{"en":"True and specific, but cold: nobody talks like this. Say it as you would to a friend: \"We roast every bean ourselves.\"","tr":"Doğru ve net ama soğuk; kimse böyle konuşmaz. Bir arkadaşına söyler gibi yaz: \"We roast every bean ourselves.\"","fa":"درست و دقیق است ولی سرد؛ کسی این‌طور حرف نمی‌زند. طوری بگو که به یک دوست می‌گویی: «We roast every bean ourselves.»"}}]},"writing":{"id":"c-mkt-1-w","title":{"en":"Your voice sheet and About text","tr":"Marka sesi sayfan ve Hakkımızda metnin","fa":"برگه‌ی صدا و متن «درباره‌ی ما»"},"course":"marketing","unit":"mkt-1","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Write a voice sheet and a short About text (70-90 words in total) for your own brand, or for this one: a ceramics studio in Kutahya, open since 2015, handmade mugs, used to sell only to local cafes, now ships to Europe. Give three traits as \"X, not Y\". Then write what the brand used to do, what it does now, and one true fact.","tr":"Kendi markan ya da şu marka için bir ses sayfası ve kısa bir Hakkımızda metni yaz (toplam 70-90 kelime): Kütahya'da 2015'ten beri çalışan, el yapımı kupalar üreten, eskiden yalnızca yerel kafelere satan, şimdi Avrupa'ya gönderen bir seramik atölyesi. Üç özelliği \"X, not Y\" biçiminde ver. Sonra markanın eskiden ne yaptığını, şimdi ne yaptığını ve doğru bir bilgi yaz.","fa":"برای برند خودت یا این برند یک برگه‌ی صدا و یک متن کوتاه «درباره‌ی ما» بنویس (در مجموع ۷۰ تا ۹۰ کلمه): یک کارگاه سرامیک در کوتاهیه، از سال ۲۰۱۵، لیوان‌های دست‌ساز، قبلاً فقط به کافه‌های محلی می‌فروخت و حالا به اروپا می‌فرستد. سه ویژگی را به شکل «X, not Y» بیاور. بعد بنویس برند قبلاً چه می‌کرد، حالا چه می‌کند و یک واقعیت درست هم بیاور."},"model":"Our voice: warm, not cute. Plain, not boring. Exact, not cold.\n\nAbout us: Since 2015 we have made mugs by hand in Kutahya. We used to sell them only to local cafes, and regulars kept asking where to buy one. Now we ship to Europe. Every mug is thrown, glazed and packed in our own studio, so we know each one before it leaves. We tell you what it is made of and how to look after it.","frame":"Our voice: ___, not ___. ___, not ___. ___, not ___.\n\nAbout us: Since ___, we have ___. We used to ___. Now we ___. Every ___, so ___. We ___.","words":[{"word":"used to"},{"word":"now"},{"word":"not"}],"minWords":60,"minSentences":5,"rubric":["Task done: three traits with what they are not, then, now, one true fact","Organised: the voice first, then the past, today and the promise","Language: used to for the past; present simple for today","Tone: the About text sounds like the three traits; every claim is true"],"rubricI18n":{"tr":["Görev: ne olmadığıyla birlikte üç özellik, önce, şimdi, doğru bir bilgi","Düzen: önce ses, sonra geçmiş, bugün ve söz","Dil: geçmiş için used to; bugün için geniş zaman","Üslup: metin üç özelliğe uyuyor; her iddia doğru"],"fa":["کامل بودن کار: سه ویژگی همراه با آنچه نیستند، قبلاً، حالا، یک واقعیت درست","نظم: اول صدا، بعد گذشته، امروز و قول","زبان: used to برای گذشته؛ حال ساده برای امروز","لحن: متن با سه ویژگی هماهنگ است؛ همه‌ی ادعاها درست‌اند"]}},"speaking":{"id":"mkt-1","course":"marketing","unit":"mkt-1","topic":{"en":"Explaining a brand voice to a writer","tr":"Marka sesini bir yazara anlatmak","fa":"توضیح صدای برند برای یک نویسنده"},"warmup":{"en":"Think of a brand you like. In three words, how does it sound?","tr":"Sevdiğin bir markayı düşün. Üç kelimeyle nasıl bir sesi var?","fa":"به برندی که دوست داری فکر کن. در سه کلمه، چه صدایی دارد؟"},"questions":[{"en":"A freelance writer asks: \"How should your brand sound?\" Give three traits.","tr":"Serbest çalışan bir yazar soruyor: \"Markanız nasıl duyulmalı?\" Üç özellik söyle.","fa":"یک نویسنده‌ی فریلنس می‌پرسد: «برندتان باید چه صدایی داشته باشد؟» سه ویژگی بگو."},{"en":"Say what each trait does not mean, with one example.","tr":"Her özelliğin ne anlama gelmediğini bir örnekle söyle.","fa":"با یک مثال بگو هر ویژگی چه معنایی ندارد."},{"en":"Say what the brand used to do and what it does now.","tr":"Markanın eskiden ne yaptığını ve şimdi ne yaptığını söyle.","fa":"بگو برند قبلاً چه می‌کرد و حالا چه می‌کند."}],"followups":[{"en":"Now do the same for your own brand, or one you work with.","tr":"Şimdi aynısını kendi markan ya da birlikte çalıştığın bir marka için yap.","fa":"حالا همین کار را برای برند خودت، یا برندی که با آن کار می‌کنی، انجام بده."}],"expressions":[{"phrase":"We want to sound..., not...","meaning":{"en":"Gives a trait and its limit.","tr":"Bir özelliği ve sınırını söyler.","fa":"یک ویژگی و حدش را می‌گوید."}},{"phrase":"We would write..., but never...","meaning":{"en":"Shows the voice with an example.","tr":"Sesi bir örnekle gösterir.","fa":"صدا را با یک مثال نشان می‌دهد."}},{"phrase":"We used to..., but now we...","meaning":{"en":"Shows the change in one sentence.","tr":"Değişikliği tek cümlede gösterir.","fa":"تغییر را در یک جمله نشان می‌دهد."}}],"model":"We want to sound warm, not cute. We want to sound plain, not boring, and exact, not cold. So we would write 'Roasted on Tuesday, with you by Friday', but never 'A world-class coffee experience'. We used to sell only to local cafes, but now we sell online, so our readers don't know us yet. Every line has to earn their trust.","selfCheck":[{"en":"I gave three traits.","tr":"Üç özellik söyledim.","fa":"سه ویژگی گفتم."},{"en":"I said what each trait does not mean.","tr":"Her özelliğin ne anlama gelmediğini söyledim.","fa":"گفتم هر ویژگی چه معنایی ندارد."},{"en":"I used \"used to\" for the past and \"now\" for today.","tr":"Geçmiş için \"used to\", bugün için \"now\" kullandım.","fa":"برای گذشته «used to» و برای امروز «now» به کار بردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-1-x","course":"marketing","unit":"mkt-1","type":"exit","items":[{"from":"mkt-1","kind":"blank","prompt":"When I started out, I ___ write only for local shops.","options":["use to","was used to","used to"],"correct":2,"point":2},{"from":"mkt-1","kind":"mcq","prompt":"Which is a trait on a good voice sheet?","options":["Warm, not cute.","Be the best.","Premium and modern."],"correct":0,"point":1},{"from":"mkt-1","kind":"mcq","prompt":"What should change between a launch post and a reply to a complaint?","options":["The tone","The voice","The facts"],"correct":0,"point":1},{"from":"mkt-1","kind":"blank","prompt":"Ten years ago we ___ have a website at all.","options":["didn't use to","don't use to","weren't use to"],"correct":0,"point":2},{"from":"mkt-1","kind":"mcq","prompt":"Which line could only one brand say?","options":["We care about quality.","We offer the best service.","Every mug is thrown by hand in our Kutahya studio."],"correct":2,"point":1},{"from":"mkt-1","kind":"blank","prompt":"Our writers ___ working with short deadlines; they do it every week.","options":["are used to","used to","use to"],"correct":0,"point":2}]},"explain":{"id":"c-mkt-1-e","course":"marketing","unit":"mkt-1","type":"explain","level":"B1","title":{"en":"Finding your brand voice","tr":"Marka sesini bulmak","fa":"پیدا کردن صدای برند"},"objective":{"en":"In this lesson you will learn to describe a brand voice and write in it.","tr":"Bu derste bir marka sesini tanımlamayı ve o sesle yazmayı öğreneceksin.","fa":"در این درس یاد می‌گیری صدای یک برند را توصیف کنی و با همان صدا بنویسی."},"hook":{"en":"A brand voice is not a mood. It is a choice you write down, then use in every line.","tr":"Marka sesi bir ruh hâli değildir. Yazıya döktüğün ve her satırda kullandığın bir seçimdir.","fa":"صدای برند یک حس مبهم نیست؛ انتخابی است که آن را مکتوب می‌کنی و بعد در هر خط به کار می‌بری."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Write a voice sheet","tr":"Marka sesi sayfası yaz","fa":"برگه‌ی صدای برند بنویس"},"steps":[{"en":"Voice is who you always are. Tone changes with the moment.","tr":"Ses hep aynı kalan kimliğindir. Ton ise o anki duruma göre değişir.","fa":"صدا همان کسی است که همیشه هستی. لحن با موقعیت عوض می‌شود.","ex":"Launch post: cheerful. Complaint reply: serious. Same voice."},{"en":"Pick three traits, and say what each one does not mean.","tr":"Üç özellik seç ve her birinin ne anlama gelmediğini de söyle.","fa":"سه ویژگی انتخاب کن و بگو هر کدام چه معنایی ندارد.","ex":"Warm, not cute. Plain, not boring. Exact, not cold."},{"en":"Show each trait with a line you would write, and one you wouldn't.","tr":"Her özelliği yazacağın bir satırla ve yazmayacağın bir satırla göster.","fa":"هر ویژگی را با خطی که می‌نویسی و خطی که نمی‌نویسی نشان بده.","ex":"Yes: Roasted Tuesday, posted Wednesday. No: World-class coffee."},{"en":"Read your draft aloud. Cut any line another brand could sign.","tr":"Taslağını yüksek sesle oku. Başka bir markanın da imzalayabileceği satırları çıkar.","fa":"پیش‌نویست را بلند بخوان. هر خطی را که برند دیگری هم می‌تواند پایش را امضا کند حذف کن.","ex":"Cut: Quality products for all your needs."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Then and now: used to, and now + present simple","tr":"Önce ve şimdi: used to ve now + geniş zaman","fa":"قبلاً و حالا: used to و now + حال ساده"},"steps":[{"en":"Past habit, not true now: used to + base verb.","tr":"Artık doğru olmayan geçmiş alışkanlık: used to + yalın fiil.","fa":"عادت گذشته که حالا دیگر نیست: used to + فعل ساده.","ex":"We used to make towels only for other brands."},{"en":"Today's fact: present simple, often with now.","tr":"Bugünkü durum: geniş zaman, çoğu zaman now ile.","fa":"واقعیت امروز: حال ساده، اغلب با now.","ex":"Now we also sell our own brand."},{"en":"Questions and negatives: did or didn't + use to.","tr":"Soru ve olumsuz: did ya da didn't + use to.","fa":"سؤال و منفی: did یا didn't + use to.","ex":"Did you use to export? We didn't use to."},{"en":"be used to + -ing is different: \"be familiar with\".","tr":"be used to + -ing farklıdır: \"alışkın olmak\".","fa":"be used to + ‎-ing فرق دارد: «عادت داشتن به».","ex":"Our sales team is used to selling on price."}],"table":{"headers":{"en":["Then (not true now)","Now"],"tr":["Önce (artık doğru değil)","Şimdi"],"fa":["قبلاً (حالا دیگر نه)","حالا"]},"rows":[["We used to make towels only for other brands.","Now we also sell our own brand."],["We didn't use to have a web shop.","Now we sell online every day."],["Did you use to sell in Germany?","Do you sell in Germany now?"]]},"tip":{"en":"Turkish says a past habit with the -ar/-ır + -dı ending (yapardık) and Persian with the past continuous (می‌ساختیم). English needs used to, and learners often drop the -d or add be.","tr":"Türkçede geçmişteki alışkanlık geniş zamanın hikâyesiyle anlatılır: \"yapardık\". İngilizcede bunun için used to gerekir; en sık hatalar -d'yi düşürmek (use to) ya da başına be eklemektir (are used to).","fa":"در فارسی عادت گذشته را با ماضی استمراری می‌گوییم («می‌ساختیم»). انگلیسی برای همین معنا used to دارد؛ اشتباه رایج این است که ‎-d حذف شود (use to) یا be اضافه شود (are used to)."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"A voice sheet your team will really use","tr":"Ekibinin gerçekten kullanacağı bir ses sayfası","fa":"برگه‌ی صدایی که تیمت واقعاً از آن استفاده کند"},"body":{"en":"Keep it to one page: three traits, with one yes line and one no line for each. Give the same page to freelancers and paste it into your AI prompts, so every draft starts in the same voice.","tr":"Tek sayfada tut: üç özellik ve her biri için bir evet, bir hayır satırı. Aynı sayfayı serbest çalışanlara ver ve yapay zekâ komutlarına yapıştır; böylece her taslak aynı sesle başlar.","fa":"آن را در یک صفحه نگه دار: سه ویژگی، برای هر کدام یک خط «آره» و یک خط «نه». همین صفحه را به فریلنسرها بده و در پرامپت‌های هوش مصنوعی بچسبان تا هر پیش‌نویس با یک صدا شروع شود."},"phrases":[{"phrase":"We want to sound..., not...","meaning":{"en":"Gives a trait and its limit.","tr":"Bir özelliği ve sınırını söyler.","fa":"یک ویژگی و حدش را می‌گوید."}},{"phrase":"We would write..., but never...","meaning":{"en":"Shows the voice with an example.","tr":"Sesi bir örnekle gösterir.","fa":"صدا را با یک مثال نشان می‌دهد."}},{"phrase":"We used to..., but now we...","meaning":{"en":"Shows the change in one sentence.","tr":"Değişikliği tek cümlede gösterir.","fa":"تغییر را در یک جمله نشان می‌دهد."}},{"phrase":"brand voice","meaning":{"en":"The way a brand always sounds, in every text.","tr":"marka sesi","fa":"صدای برند"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Put a line into the voice","tr":"Bir satırı marka sesine çevir","fa":"یک خط را به صدای برند برگردان"},"item":"We offer world-class coffee of the highest quality.","answer":"We have roasted coffee in Izmir since 2011. We roast your order on Tuesday and post it on Wednesday.","walk":[{"en":"Check the sheet: warm, plain, exact. Which trait is missing?","tr":"Sayfaya bak: sıcak, sade, net. Hangi özellik eksik?","fa":"برگه را نگاه کن: گرم، ساده، دقیق. کدام ویژگی کم است؟"},{"en":"Swap the big words for a fact: a place, a year, a product.","tr":"Büyük lafların yerine bir gerçek koy: bir yer, bir yıl, bir ürün.","fa":"به‌جای کلمه‌های بزرگ یک واقعیت بگذار: یک مکان، یک سال، یک محصول."},{"en":"Read it aloud. Could only this brand say it? Then keep it.","tr":"Yüksek sesle oku. Bunu yalnızca bu marka söyleyebilir mi? O zaman kalsın.","fa":"آن را بلند بخوان. فقط همین برند می‌تواند این را بگوید؟ پس نگهش دار."}]},"quick":{"prompt":"A brand keeps one voice, but its ___ changes with the moment.","options":["tone","name","product"],"correct":0,"why":{"en":"tone: a reply to a complaint sounds more serious than a launch post, but the same brand is speaking.","tr":"tone: bir şikâyete verilen cevap, lansman gönderisinden daha ciddi duyulur ama konuşan aynı markadır.","fa":"tone: جواب یک شکایت جدی‌تر از پست معرفی محصول است، ولی همان برند دارد حرف می‌زند."}},"remember":{"en":"Could another brand sign this line? Then it is not your voice yet.","tr":"Bu satırı başka bir marka da imzalayabilir mi? O zaman henüz senin sesin değil.","fa":"برند دیگری هم می‌تواند پای این خط را امضا کند؟ پس هنوز صدای تو نیست."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"News about the future: be set to, be due to, be about to","tr":"Gelecekle ilgili haberler: be set to, be due to, be about to","fa":"خبر درباره‌ی آینده: be set to، be due to، be about to"},"steps":[{"en":"Planned and expected: be set to + verb.","tr":"Planlanmış ve beklenen: be set to + fiil.","fa":"برنامه‌ریزی‌شده و مورد انتظار: be set to + فعل.","ex":"The brand is set to launch in December."},{"en":"On a schedule, often with a date: be due to + verb.","tr":"Takvime bağlı, çoğu zaman tarihli: be due to + fiil.","fa":"طبق برنامه، اغلب با تاریخ: be due to + فعل.","ex":"The samples are due to arrive on Friday."},{"en":"Very soon: be about to + verb.","tr":"Çok yakında: be about to + fiil.","fa":"خیلی زود: be about to + فعل.","ex":"We are about to open the web shop."}],"table":{"headers":{"en":["Form","Meaning","Example"],"tr":["Yapı","Anlam","Örnek"],"fa":["ساختار","معنی","مثال"]},"rows":[["be set to","planned and expected","The brand is set to launch in December."],["be due to","on a schedule, often with a date","The samples are due to arrive on Friday."],["be about to","very soon","We are about to open the web shop."]]},"body":{"en":"B2: in your \"About us\" text, announce one future event with be set to, be due to or be about to.","tr":"B2: \"Hakkımızda\" metninde gelecekteki bir olayı be set to, be due to ya da be about to ile duyur.","fa":"B2: در متن «درباره‌ی ما»، یک رویداد آینده را با be set to یا be due to یا be about to اعلام کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
